def b64url_decode(data):
    padding = '=' * (4 - (len(data) % 4))
    return base64.urlsafe_b64decode(data + padding)

# 1. Parse JWT
parts = JWT.split('.')
signing_input = f"{parts[0]}.{parts[1]}".encode('utf-8')
signature_bytes = b64url_decode(parts[2])

# 2. Extract exactly 1952 bytes (bypassing Java ASN.1 OID headers)
der_bytes = base64.b64decode(PEM_B64)
raw_pubkey = der_bytes[-1952:]

# 3. Cryptographic Verification
try:
    with oqs.Signature('ML-DSA-65') as verifier:
        if verifier.verify(signing_input, signature_bytes, raw_pubkey):
            print("\n[SUCCESS] Cryptographic FIPS 204 verification passed!")
        else:
            print("\n[FAILED] Signature is invalid.")
except Exception as e:
    print(f"\n[FATAL] liboqs error: {e}")